/**
 * IOS-12f (PC-L1, one Chat; NS-D1 A, NS-D2 B, NS-D5; VF-PM 2026-11-07 12:35:44Z) — THE NEW SPARK SHEET'S GOLDENS,
 * generated by the Mac's own model (`new-spark.ts`). Each case is what the sheet reads, in: `agent.providers`' rows,
 * `agents.profileSets.list`'s sets, `agent.models`' answers, a hatch's refusal. What the model says comes out: the name
 * it suggests, the agents its menu lists and why one waits, the menu's rows and Effort, the pill's words, the
 * profiles' chips and reach, and where a refusal is said. The phone's port (the kit's `NewSpark`) is held to the same
 * files, copied to `Tests/FieldHomeTests/Fixtures/new-spark/` and pinned byte for byte by `pnpm check:ios-fixtures`.
 * A change to the model changes a golden here, and the kit's row is red until the port follows.
 *
 * The wire's inputs are the contracts' own fixtures where one exists (`agent-providers.valid.json`,
 * `agents-profile-sets.*.json`, `agent-models.*.json`), each written into the golden whole, so the kit reads what it
 * decodes. Agents are the catalog's rows (R23b), their labels written as the model read them. The sheet's controller
 * (`NewSparkSheet.tsx`: the first agent that takes, the default profile, the profiles it sees) is not a golden; the
 * kit's rows hold its port to DESIGN.md §8. The phone calls a native set Default (PJ-7) above the model, never in it.
 *
 * `VF_WRITE_GOLDENS=1` writes the files; without it, each file must equal what the model says now, byte for byte.
 */

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  AGENT_CATALOG,
  type AgentModelChoice,
  type AgentModelSelection,
  type AgentModelsResult,
  type AgentProfileSet,
  type AgentProviderSummary,
  type RunProfileFacts,
} from "@vibefield/contracts";
import { describe, expect, it } from "vitest";
import {
  agentLine,
  agentMenuOf,
  CANNOT_LIST_AGENTS,
  CANNOT_LIST_PROFILES,
  CANNOT_TAKE_TOOLS,
  dealSeed,
  defaultProfileOf,
  effortOf,
  listWords,
  type ModelsReading,
  modelWords,
  profileChipsOf,
  reachOf,
  refusalOf,
  type SparkAgent,
  STAR_NAMES,
  sessionsSeenOf,
  sparkAgentsOf,
  startsOf,
  suggestName,
} from "../src/chat/new-spark";

const here = dirname(fileURLToPath(import.meta.url));
const GOLDENS = join(here, "fixtures/new-spark");
const WRITE = process.env.VF_WRITE_GOLDENS === "1";
const GENERATED =
  "GENERATED by packages/field-app/test/new-spark-goldens.test.ts (VF_WRITE_GOLDENS=1): edit the case there, never here";

/** One of the contracts' fixtures, as fieldd hands it. */
const fixture = <T>(name: string): T =>
  JSON.parse(readFileSync(join(here, "../../contracts/fixtures", `${name}.json`), "utf8")) as T;

/** A golden as the generator writes it: two-space JSON and a final newline, formatted by nothing else. */
const textOf = (golden: unknown): string => `${JSON.stringify(golden, null, 2)}\n`;

/** Written under `VF_WRITE_GOLDENS=1`; else the committed file must be what the model says now, byte for byte. */
function holds(file: string, golden: unknown): void {
  const path = join(GOLDENS, file);
  const text = textOf(golden);
  if (WRITE) {
    mkdirSync(GOLDENS, { recursive: true });
    writeFileSync(path, text);
  }
  expect(readFileSync(path, "utf8"), `${file} is not what the model says now`).toBe(text);
}

/** An absent answer, as JSON can hold it. */
const orNull = <T>(value: T | undefined): T | null => (value === undefined ? null : value);

// ── the wire's inputs ──

const PROVIDERS = fixture<{ providers: AgentProviderSummary[] }>("agent-providers.valid").providers;
const SETS = fixture<{ sets: AgentProfileSet[] }>("agents-profile-sets.valid").sets;
const SETS_MANY = fixture<{ sets: AgentProfileSet[] }>("agents-profile-sets.meters").sets;
const MODELS = fixture<AgentModelsResult>("agent-models.valid");
const MODELS_SIGN_IN = fixture<AgentModelsResult>("agent-models.auth-required");
const MODELS_STALE = fixture<AgentModelsResult>("agent-models.stale");
/** An answer with neither a catalog nor a failure: the picker lists nothing and says so. */
const MODELS_NONE: AgentModelsResult = {
  provider: MODELS.provider,
  profileSet: MODELS.profileSet,
  refreshing: false,
};

const [FIRST, SECOND, THIRD] = [AGENT_CATALOG[0], AGENT_CATALOG[1], AGENT_CATALOG[2]];

/** A row of `agent.providers` for one of the catalog's agents. */
const provider = (
  entry: { readonly id: string; readonly label: string },
  shape: {
    readonly available?: boolean;
    readonly briefing?: AgentProviderSummary["briefing"];
    readonly offers?: AgentProviderSummary["offers"];
  } = {},
): AgentProviderSummary => ({
  id: entry.id,
  label: entry.label,
  available: shape.available ?? true,
  resumable: true,
  personas: [],
  ...(shape.briefing === undefined ? {} : { briefing: shape.briefing }),
  ...(shape.offers === undefined ? {} : { offers: shape.offers }),
});

const BRIEFED = { mcpServers: true, allowTools: true, instructions: true } as const;
const BRIEFED_TERMINAL = { ...BRIEFED, mcpServerProcess: "terminal" } as const;

// ── the name ──

function namesGolden() {
  const taken = [[], ["polaris", "Capella"], ["Polaris", "Altair"], ["POLARIS"], [...STAR_NAMES]];
  return {
    "//": GENERATED,
    starNames: STAR_NAMES,
    suggest: taken.map((held) => ({ taken: held, name: suggestName(held) })),
    deal: [0, 0.25, 0.5, 0.999999999].map((random) => ({ random, seed: dealSeed(() => random) })),
  };
}

// ── the agents ──

const AGENT_CASES: { name: string; about: string; providers: AgentProviderSummary[] }[] = [
  {
    name: "fixture",
    about: "the contracts' rows: one a spark, one not installed",
    providers: PROVIDERS,
  },
  {
    name: "claim-false",
    about: "installed, and the catalog does not let it be a spark here: listed, disabled, with why",
    providers: [provider(FIRST, { briefing: BRIEFED_TERMINAL, offers: { spark: false } })],
  },
  {
    name: "claim-true",
    about: "fieldd's claim wins over the facts",
    providers: [provider(FIRST, { offers: { spark: true } })],
  },
  {
    name: "no-claim-briefed",
    about:
      "an older daemon, no claim: read by the briefing it declares, with a process the door can name",
    providers: [provider(FIRST, { briefing: BRIEFED_TERMINAL })],
  },
  {
    name: "no-claim-no-process",
    about: "an older daemon whose briefing names no terminal process: not yet",
    providers: [provider(FIRST, { briefing: BRIEFED })],
  },
  {
    name: "no-claim-no-briefing",
    about: "an older daemon with no briefing: not yet",
    providers: [provider(FIRST)],
  },
  {
    name: "order",
    about:
      "sparks first, then the ones it does not let yet, each in agent.providers' order; one not installed is not listed",
    providers: [
      provider(FIRST, { offers: { spark: false } }),
      provider(SECOND, { offers: { spark: true } }),
      provider(THIRD, { available: false, offers: { spark: true } }),
    ],
  },
  { name: "none", about: "the home lists no agent", providers: [] },
];

function agentsGolden() {
  return {
    "//": GENERATED,
    words: {
      cannotTakeTools: CANNOT_TAKE_TOOLS,
      cannotListAgents: CANNOT_LIST_AGENTS,
      cannotListProfiles: CANNOT_LIST_PROFILES,
    },
    cases: AGENT_CASES.map((agentCase) => ({
      ...agentCase,
      agents: sparkAgentsOf(agentCase.providers),
    })),
  };
}

// ── the menu, its Effort and the pill ──

/** The menu's agents: two a spark, one that cannot be one yet. */
const MENU_AGENTS: SparkAgent[] = sparkAgentsOf([
  provider(FIRST, { offers: { spark: true } }),
  provider(SECOND, { offers: { spark: false } }),
  provider(THIRD, { offers: { spark: true } }),
]);

/** The first of them, the agent the pill cases say. */
const PILL_AGENT: SparkAgent = (() => {
  const agent = MENU_AGENTS[0];
  if (agent === undefined) throw new Error("the menu's fixture lists no agent");
  return agent;
})();

const modelOf = (answer: AgentModelsResult, id: string): AgentModelChoice => {
  const found = answer.catalog?.models.find((model) => model.id === id);
  if (found === undefined) throw new Error(`no model ${id} in the fixture`);
  return found;
};

/** The picker's answers the menu cases read, each written once in the golden and named by its case. */
const ANSWERS = {
  valid: MODELS,
  "sign-in": MODELS_SIGN_IN,
  none: MODELS_NONE,
  stale: MODELS_STALE,
} as const;

/** A picker as a case names it: being read, failed with its words, or read, by its answer's name. */
type Picker =
  | { readonly state: "reading" }
  | { readonly state: "failed"; readonly words: string }
  | { readonly state: "read"; readonly answer: keyof typeof ANSWERS };

const readingOf = (picker: Picker | undefined): ModelsReading | undefined =>
  picker?.state === "read" ? { state: "read", answer: ANSWERS[picker.answer] } : picker;

const MENU_CASES: {
  name: string;
  about: string;
  chosen?: string;
  picker?: Picker;
  selection?: AgentModelSelection;
  under?: string;
}[] = [
  { name: "none-chosen", about: "every agent's head alone" },
  { name: "unread", about: "chosen, its picker not asked yet: being read", chosen: FIRST.id },
  {
    name: "reading",
    about: "its picker being read",
    chosen: FIRST.id,
    picker: { state: "reading" },
  },
  {
    name: "failed",
    about: "its picker could not be read: why, in place of the models",
    chosen: FIRST.id,
    picker: { state: "failed", words: "studio didn't answer" },
  },
  {
    name: "read",
    about: "its own model first, chosen while untouched, then the picker's models",
    chosen: FIRST.id,
    picker: { state: "read", answer: "valid" },
  },
  {
    name: "read-chosen",
    about: "a model chosen",
    chosen: FIRST.id,
    picker: { state: "read", answer: "valid" },
    selection: { modelId: "opus", controls: { effort: "high" } },
  },
  {
    name: "under",
    about: "the profile it thinks under, on the chosen agent's head",
    chosen: FIRST.id,
    picker: { state: "read", answer: "valid" },
    under: "Work",
  },
  {
    name: "under-other",
    about: "the profile goes on the chosen agent's head alone",
    chosen: THIRD.id,
    picker: { state: "reading" },
    under: "Work",
  },
  {
    name: "sign-in",
    about: "no catalog, and the failure's words",
    chosen: FIRST.id,
    picker: { state: "read", answer: "sign-in" },
  },
  {
    name: "lists-none",
    about: "no catalog and no failure: it lists no models",
    chosen: FIRST.id,
    picker: { state: "read", answer: "none" },
  },
  {
    name: "stale",
    about: "a catalog with a failure beside it: the catalog's models",
    chosen: FIRST.id,
    picker: { state: "read", answer: "stale" },
  },
  {
    name: "chosen-cannot",
    about: "an agent that cannot be a spark is never the chosen one",
    chosen: SECOND.id,
    picker: { state: "reading" },
  },
];

const EFFORT_CASES: {
  name: string;
  about: string;
  model?: AgentModelChoice;
  selection?: AgentModelSelection;
}[] = [
  { name: "untouched", about: "no model chosen: no Effort", model: modelOf(MODELS, "opus") },
  {
    name: "chosen-default",
    about: "a model chosen, its effort untouched: the control's default",
    model: modelOf(MODELS, "opus"),
    selection: { modelId: "opus" },
  },
  {
    name: "chosen-high",
    about: "an effort chosen",
    model: modelOf(MODELS, "opus"),
    selection: { modelId: "opus", controls: { effort: "high" } },
  },
  {
    name: "no-effort",
    about: "a model with no effort control",
    model: modelOf(MODELS, "haiku"),
    selection: { modelId: "haiku" },
  },
  {
    name: "future-role",
    about: "a control of a role this build does not know beside the effort",
    model: modelOf(MODELS_STALE, "opus"),
    selection: { modelId: "opus", controls: { effort: "xhigh", thinking: "on" } },
  },
  { name: "no-model", about: "nothing chosen at all" },
];

const PILL_CASES: {
  name: string;
  about: string;
  agent?: SparkAgent;
  model?: AgentModelChoice;
  selection?: AgentModelSelection;
}[] = [
  { name: "no-agent", about: "no agent can be a spark" },
  {
    name: "untouched",
    about: "the agent alone: it thinks at its own model",
    agent: PILL_AGENT,
  },
  {
    name: "model",
    about: "a model chosen with no effort value",
    agent: PILL_AGENT,
    model: modelOf(MODELS, "haiku"),
    selection: { modelId: "haiku" },
  },
  {
    name: "model-effort",
    about: "a model and its effort",
    agent: PILL_AGENT,
    model: modelOf(MODELS, "opus"),
    selection: { modelId: "opus", controls: { effort: "high" } },
  },
];

function menuGolden() {
  return {
    "//": GENERATED,
    agents: MENU_AGENTS,
    answers: ANSWERS,
    menu: MENU_CASES.map((menuCase) => ({
      ...menuCase,
      rows: agentMenuOf(
        MENU_AGENTS,
        menuCase.chosen,
        readingOf(menuCase.picker),
        menuCase.selection,
        menuCase.under,
      ),
    })),
    effort: EFFORT_CASES.map((effortCase) => ({
      ...effortCase,
      effort: orNull(effortOf(effortCase.model, effortCase.selection)),
    })),
    pill: PILL_CASES.map((pillCase) => ({
      ...pillCase,
      words: modelWords(pillCase.model, pillCase.selection),
      line: agentLine(pillCase.agent, pillCase.model, pillCase.selection),
    })),
  };
}

// ── the profiles ──

/** The agents the profiles' personas name, each a spark, labelled as the catalog labels it (else by its id). */
const PERSONA_AGENTS: SparkAgent[] = sparkAgentsOf(
  [
    ...new Set(
      [...SETS, ...SETS_MANY].flatMap((set) => set.personas.map((persona) => persona.provider)),
    ),
  ].map((id) =>
    provider(
      { id, label: AGENT_CATALOG.find((entry) => entry.id === id)?.label ?? id },
      { offers: { spark: true } },
    ),
  ),
);

/** The person's live sessions as the board places them (TU-1's one rule). */
const SESSIONS: RunProfileFacts[] = [
  { profileSet: "work" },
  {},
  { profileId: SETS_MANY[1]?.personas[0]?.profileId },
  { profileId: "retired-sign-in" },
  { profileSet: "side" },
];

const CHIP_CASES: {
  name: string;
  sets: AgentProfileSet[];
  chosen: string[];
  thinksUnder?: string;
}[] = [
  { name: "two", sets: SETS, chosen: ["work"], thinksUnder: "work" },
  { name: "many", sets: SETS_MANY, chosen: ["work", "side"], thinksUnder: "work" },
  { name: "under-only", sets: SETS_MANY, chosen: [], thinksUnder: "native" },
  { name: "under-unread", sets: SETS_MANY, chosen: ["side"] },
];

function profilesGolden() {
  return {
    "//": GENERATED,
    sets: { two: SETS, many: SETS_MANY },
    defaultOf: [
      { name: "two", sets: "two", id: orNull(defaultProfileOf(SETS)?.id) },
      { name: "many", sets: "many", id: orNull(defaultProfileOf(SETS_MANY)?.id) },
      {
        name: "none-marked",
        sets: "two:first",
        id: orNull(defaultProfileOf(SETS.slice(0, 1))?.id),
      },
      { name: "none", sets: "none", id: orNull(defaultProfileOf([])?.id) },
    ],
    chips: CHIP_CASES.map((chipCase) => ({
      name: chipCase.name,
      sets: chipCase.sets === SETS ? "two" : "many",
      chosen: chipCase.chosen,
      ...(chipCase.thinksUnder === undefined ? {} : { thinksUnder: chipCase.thinksUnder }),
      chips: profileChipsOf(chipCase.sets, chipCase.chosen, chipCase.thinksUnder),
      starts: startsOf(chipCase.sets, chipCase.chosen, chipCase.thinksUnder, PERSONA_AGENTS),
    })),
    agents: PERSONA_AGENTS,
    sessions: SESSIONS,
    seen: [
      { name: "board-unread", read: false, sets: "many", chosen: ["work"] },
      { name: "work", read: true, sets: "many", chosen: ["work"] },
      { name: "native", read: true, sets: "many", chosen: ["native"] },
      { name: "three", read: true, sets: "many", chosen: ["work", "side", "native"] },
      { name: "profiles-unread", read: true, sets: "none", chosen: ["work"] },
    ].map((seenCase) => ({
      ...seenCase,
      count: sessionsSeenOf(
        seenCase.read ? SESSIONS : null,
        seenCase.sets === "many" ? SETS_MANY : [],
        seenCase.chosen,
      ),
    })),
    reach: [
      { sessions: null, starts: [] },
      { sessions: null, starts: [FIRST.label] },
      { sessions: 0, starts: [] },
      { sessions: 1, starts: [FIRST.label] },
      { sessions: 3, starts: [FIRST.label, SECOND.label] },
      { sessions: 2, starts: [FIRST.label, SECOND.label, THIRD.label] },
    ].map((reachCase) => ({ ...reachCase, words: reachOf(reachCase.sessions, reachCase.starts) })),
    list: [[], ["Claude Code"], ["Claude Code", "Codex"], ["Claude Code", "Codex", "Grok"]].map(
      (words) => ({
        words,
        said: listWords(words),
      }),
    ),
  };
}

// ── a hatch's refusal ──

const REFUSAL_CASES: {
  name: string;
  thrown: { message: string; reason?: string } | string;
  ask: { name: string; agent?: string; profile?: string };
}[] = [
  {
    name: "name-taken",
    thrown: { message: "name held", reason: "name-taken" },
    ask: { name: "Vela" },
  },
  {
    name: "no-sign-in",
    thrown: { message: "no sign-in", reason: "no-sign-in" },
    ask: { name: "Vela", agent: FIRST.label, profile: "Work" },
  },
  {
    name: "no-sign-in-unnamed",
    thrown: { message: "Work holds no sign-in for this agent", reason: "no-sign-in" },
    ask: { name: "Vela", agent: FIRST.label },
  },
  {
    name: "unknown-profile",
    thrown: { message: "unknown profile", reason: "unknown-profile" },
    ask: { name: "Vela", agent: FIRST.label, profile: "Work" },
  },
  {
    name: "other-reason",
    thrown: { message: "the agent cannot start here", reason: "agent-unavailable" },
    ask: { name: "Vela" },
  },
  {
    name: "no-reason",
    thrown: { message: "UNAVAILABLE: compose is starting" },
    ask: { name: "Vela" },
  },
  { name: "not-an-error", thrown: "the home closed the door", ask: { name: "Vela" } },
];

/** What the port's client throws: an Error with fieldd's details, or (from anything else) a bare value. */
const thrownOf = (thrown: { message: string; reason?: string } | string): unknown =>
  typeof thrown === "string"
    ? thrown
    : Object.assign(new Error(thrown.message), {
        ...(thrown.reason === undefined ? {} : { details: { reason: thrown.reason } }),
      });

function refusalsGolden() {
  return {
    "//": GENERATED,
    cases: REFUSAL_CASES.map((refusalCase) => ({
      ...refusalCase,
      refusal: refusalOf(thrownOf(refusalCase.thrown), refusalCase.ask),
    })),
  };
}

// ── the rows ──

describe("the New spark sheet's goldens (IOS-12f): what the Mac's model says, for the phone's port", () => {
  it("the name it suggests, and the faces it deals", () => {
    holds("new-spark.names.golden.json", namesGolden());
  });

  it("the agents its menu lists, and why one waits", () => {
    holds("new-spark.agents.golden.json", agentsGolden());
  });

  it("the agent menu's rows, its Effort, and the pill's words", () => {
    holds("new-spark.menu.golden.json", menuGolden());
  });

  it("the profiles' chips, what they start and see, and the reach", () => {
    holds("new-spark.profiles.golden.json", profilesGolden());
  });

  it("where a hatch's refusal is said, in the sheet's words", () => {
    holds("new-spark.refusals.golden.json", refusalsGolden());
  });
});
